"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7061],{29590:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Wraps a rig model in a Zombie, registering any per-state animations declared\\non the config with the underlying Freshynoid.\\n\\nThe zombie starts in the `Idle` state with full health, and mirrors its\\nhealth onto the model as the `Health` and `MaxHealth` attributes so other\\nsystems can read it without holding a reference to this object.","params":[{"name":"model","desc":"the rig to drive","lua_type":"Model"},{"name":"config","desc":"health, animations and behaviour tuning","lua_type":"ZombieTypes.ZombieConfig"}],"returns":[{"desc":"","lua_type":"Zombie"}],"function_type":"static","source":{"line":106,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"SetState","desc":"Transitions the zombie into a new AI state.\\n\\nStops the outgoing state module, records it as `previousState`, then starts\\nthe incoming one. No-ops when already in the requested state, and refuses\\nevery transition except `Death` once the zombie is dead. When the config\\ndeclares a `behaviorOverride`, that module is started instead of the\\nbuilt-in state module for the new state.","params":[{"name":"stateName","desc":"state to enter","lua_type":"ZombieTypes.ZombieStateName"}],"returns":[],"function_type":"method","source":{"line":164,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"Step","desc":"Advances the active state by one tick. Called by the owning zombie manager\\nevery frame (or less often for distant zombies, per `lodTier`).\\n\\nDead zombies are skipped entirely. A configured `behaviorOverride` that\\nimplements `Step` replaces the built-in state\'s step for this tick.","params":[{"name":"dt","desc":"seconds elapsed since the previous step","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":226,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"TakeDamage","desc":"Subtracts damage from the zombie\'s health, clamped at zero, and republishes\\nthe new value to the model\'s `Health` attribute. Calls [Zombie:Die] once\\nhealth reaches zero. No-ops on an already dead zombie.","params":[{"name":"amount","desc":"damage to apply","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":260,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"Die","desc":"Marks the zombie dead, transitions it into the `Death` state (which plays\\nthe death animation and ragdolls the rig) and fires `Died`. Idempotent.\\n\\nThe zombie object is not destroyed here \u2014 the owner is expected to call\\n[Zombie:Destroy] after the death sequence has played out.","params":[],"returns":[],"function_type":"method","source":{"line":287,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"GetTarget","desc":"Returns the zombie\'s current target, or nil when it has none. The target is\\nselected by the Seek/Chase states according to `targetMode`.","params":[],"returns":[{"desc":"","lua_type":"ZombieTypes.ZombieTarget?"}],"function_type":"method","source":{"line":306,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"GetPosition","desc":"Returns the world position of the underlying rig.","params":[],"returns":[{"desc":"","lua_type":"Vector3"}],"function_type":"method","source":{"line":318,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"GetModel","desc":"Returns the rig model this zombie drives.","params":[],"returns":[{"desc":"","lua_type":"Model"}],"function_type":"method","source":{"line":330,"path":"src/Server/Class/NPC/Zombie.luau"}},{"name":"Destroy","desc":"Tears the zombie down: stops the active state (skipped when already in\\n`Death`, which owns its own cleanup), destroys the `Died` signal and\\ndestroys the underlying NPC and its rig.","params":[],"returns":[],"function_type":"method","source":{"line":342,"path":"src/Server/Class/NPC/Zombie.luau"}}],"properties":[],"types":[],"name":"Zombie","desc":"Zombie NPC class. Wraps an NPC instance with health,\\nAI state machine, and damage handling.\\n\\nEach zombie owns a finite state machine whose states live in\\n`ServerScriptService.Class.NPC.States` (Idle, Roam, Chase, Attack, Death,\\nSeek, Flee). Every state module implements the same `Start`/`Step`/`Stop`\\ncontract; `SetState` stops the outgoing state and starts the incoming one,\\nwhile `Step` ticks the active state each frame. A zombie config may set\\n`behaviorOverride` to the name of a sibling module in the same States\\nfolder, which is lazily required and takes precedence over the built-in\\nstate for both `Start` and `Step`.\\n\\n:::warning Broken require\\nThis module requires `ReplicatedStorage.Shared.Types.ZombieTypes`, which\\ndoes not exist in the source tree. Every `ZombieTypes.*` annotation below\\ntherefore fails to resolve and the module cannot be loaded at runtime until\\nthat type module is authored. This is a known, pre-existing gap.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Server"],"source":{"line":65,"path":"src/Server/Class/NPC/Zombie.luau"}}')}}]);